-- Tiny Cosmos — Migration 001: Initial platform schema
-- UUIDs are generated by the application and stored as TEXT.
-- Timestamps are ISO 8601 UTC strings.
-- Enable foreign keys on every SQLite connection in the application.

PRAGMA foreign_keys = ON;

CREATE TABLE users (
    id TEXT PRIMARY KEY,
    created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now'))
);

CREATE TABLE user_identities (
    id TEXT PRIMARY KEY,
    user_id TEXT NOT NULL,
    provider TEXT NOT NULL CHECK (provider IN ('telegram', 'email', 'apple', 'google', 'phone')),
    provider_user_id TEXT NOT NULL,
    created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
    UNIQUE (provider, provider_user_id),
    FOREIGN KEY (user_id) REFERENCES users(id)
);

CREATE TABLE user_contact_methods (
    id TEXT PRIMARY KEY,
    user_id TEXT NOT NULL,
    type TEXT NOT NULL CHECK (type IN ('email', 'phone')),
    value TEXT NOT NULL,
    verified_at TEXT,
    created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
    UNIQUE (type, value),
    FOREIGN KEY (user_id) REFERENCES users(id)
);

-- Created only after an authorized group explicitly activates Tiny Cosmos.
CREATE TABLE groups (
    id TEXT PRIMARY KEY,
    created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now'))
);

CREATE TABLE group_integrations (
    id TEXT PRIMARY KEY,
    group_id TEXT NOT NULL,
    provider TEXT NOT NULL,
    external_group_id TEXT NOT NULL,
    UNIQUE (provider, external_group_id),
    FOREIGN KEY (group_id) REFERENCES groups(id)
);

CREATE TABLE group_memberships (
    group_id TEXT NOT NULL,
    user_id TEXT NOT NULL,
    status TEXT NOT NULL DEFAULT 'active' CHECK (status IN ('active', 'left')),
    PRIMARY KEY (group_id, user_id),
    FOREIGN KEY (group_id) REFERENCES groups(id),
    FOREIGN KEY (user_id) REFERENCES users(id)
);

CREATE TABLE prompts (
    id TEXT PRIMARY KEY,
    content TEXT NOT NULL,
    is_active INTEGER NOT NULL DEFAULT 1 CHECK (is_active IN (0, 1))
);

CREATE TABLE group_prompts (
    id TEXT PRIMARY KEY,
    group_id TEXT NOT NULL,
    prompt_id TEXT NOT NULL,
    status TEXT NOT NULL DEFAULT 'collecting' CHECK (status IN ('collecting', 'revealed')),
    created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
    deadline_at TEXT NOT NULL,
    revealed_at TEXT,
    UNIQUE (group_id, prompt_id),
    CHECK (
        (status = 'collecting' AND revealed_at IS NULL)
        OR
        (status = 'revealed' AND revealed_at IS NOT NULL)
    ),
    FOREIGN KEY (group_id) REFERENCES groups(id),
    FOREIGN KEY (prompt_id) REFERENCES prompts(id)
);

CREATE TABLE responses (
    id TEXT PRIMARY KEY,
    group_prompt_id TEXT NOT NULL,
    user_id TEXT NOT NULL,
    content TEXT NOT NULL,
    created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
    UNIQUE (group_prompt_id, user_id),
    FOREIGN KEY (group_prompt_id) REFERENCES group_prompts(id),
    FOREIGN KEY (user_id) REFERENCES users(id)
);

CREATE INDEX idx_user_identities_user_id ON user_identities (user_id);
CREATE INDEX idx_user_contact_methods_user_id ON user_contact_methods (user_id);
CREATE INDEX idx_group_integrations_group_id ON group_integrations (group_id);
CREATE INDEX idx_group_memberships_group_status ON group_memberships (group_id, status);
CREATE INDEX idx_group_prompts_status_deadline ON group_prompts (status, deadline_at);
CREATE INDEX idx_responses_user_id ON responses (user_id);
